B,CAAC,CAAC,CAAC,CAAC,CAAC,CAAC,CAAC,CAAC,CAAC;YACzD,MAAM,QAAQ,GAAG,aAAa,CAAC,IAAI,CAAC,CAAC;YACrC,MAAM,KAAK,GAAG,QAAQ,CAAC,CAAC,CAAC,CAAC,CAAC,CAAC,CAAC,aAAa,GAAG,uBAAuB,CAAC;YACrE,MAAM,QAAQ,GAAG,gBAAgB,KAAK,KAAK,CAAC;YAC5C,MAAM,OAAO,GAAqB;gBAC9B,CAAC,iBAAiB,CAAC,MAAM,CAAC,EAAE,GAAG,EAAE,CAAC,QAAQ,CAAC,EAAC,IAAI,EAAE,YAAY,EAAE,OAAO,EAAE,KAAK,EAAC,CAAC;aACnF,CAAC;YAEF,IAAI,CAAC,QAAQ,EAAE,CAAC;gBACZ,OAAO,CAAC,iBAAiB,CAAC,IAAI,CAAC,GAAG,GAAG,EAAE,CACnC,QAAQ,CAAC,EAAC,IAAI,EAAE,UAAU,EAAE,OAAO,EAAE,KAAK,EAAC,CAAC,CAAC;gBAEjD,IAAI,KAAK,GAAG,uBAAuB,EAAE,CAAC;oBAClC,OAAO,CAAC,iBAAiB,CAAC,EAAE,CAAC,GAAG,GAAG,EAAE,CACjC,QAAQ,CAAC;wBACL,IAAI,EAAE,WAAW;wBACjB,OAAO,EAAE,EAAC,QAAQ,EAAE,KAAK,EAAE,QAAQ,EAAE,KAAK,GAAG,CAAC,EAAC;qBAClD,CAAC,CAAC;gBACX,CAAC;gBAED,IAAI,KAAK,GAAG,OAAO,CAAC,MAAM,CAAC,MAAM,GAAG,CAAC,EAAE,CAAC;oBACpC,OAAO,CAAC,iBAAiB,CAAC,IAAI,CAAC,GAAG,GAAG,EAAE,CACnC,QAAQ,CAAC;wBACL,IAAI,EAAE,WAAW;wBACjB,OAAO,EAAE,EAAC,QAAQ,EAAE,KAAK,EAAE,QAAQ,EAAE,KAAK,GAAG,CAAC,EAAC;qBAClD,CAAC,CAAC;gBACX,CAAC;YACL,CAAC;YAED,OAAO;gBACH,QAAQ;gBACR,QAAQ;gBACR,QAAQ;gBACR,OAAO;gBACP,QAAQ,EAAE,GAAG,EAAE,CAAC,QAAQ,CAAC,KAAK,CAAC;gBAC/B,GAAG,IAAI;aACQ,CAAC;QACxB,CAAC,CAAC;QAEF,OAAO;YACH,gBAAgB;YAChB,OAAO;YACP,kBAAkB;YAClB,oBAAoB;YACpB,KAAK;YACL,QAAQ;YACR,eAAe;SAClB,CAAC;IACN,CAAC,EAAE,CAAC,OAAO,EAAE,gBAAgB,EAAE,kBAAkB,EAAE,MAAM,CAAC,CAAC,CAAC;AAChE,CAAC","sourcesContent":["import * as React from 'react';

import {DEFAULT_THEME} from '../../../components/constants';
import {Block, BlockDecorationProps, HeaderBlockTypes, PageContent} from '../../../models';
import {getCustomTypes, getHeaderBlock} from '../../../utils';
import {EditBlockActions, EditBlockControls} from '../../components/EditBlock/EditBlock';
import {EditBlockProps, EditorProps, ViewModeItem} from '../../types';

import {
    ADD_BLOCK,
    COPY_BLOCK,
    DELETE_BLOCK,
    ORDER_BLOCK,
    SELECT_BLOCK,
    UPDATE_CONTENT,
    reducer,
} from './reducer';
import {addEditorProps} from './utils';

export type EditorBlockId = number | string;

export function useMainState({content: intialContent, custom}: Omit<EditorProps, 'children'>) {
    const [{activeBlockIndex, content, errorBoundaryState}, dispatch] = React.useReducer(reducer, {
        activeBlockIndex: 0,
        errorBoundaryState: 0,
        content: addEditorProps(intialContent),
        viewMode: ViewModeItem.Desktop,
        theme: DEFAULT_THEME,
    });

    return React.useMemo(() => {
        const headerBlockTypes = [...HeaderBlockTypes, ...getCustomTypes(['headers'], custom)];
        const contentHasHeader = Boolean(getHeaderBlock(content.blocks, headerBlockTypes));
        const checkIsHeader = (type: string) => headerBlockTypes.includes(type);

        const onAdd = (block: Block) => {
            const isHeader = checkIsHeader(block.type);

            if (contentHasHeader && isHeader) {
                //TODO: add warning that it should be only one header block
                return;
            }

            // eslint-disable-next-line no-nested-ternary
            const index = isHeader
                ? 0
                : activeBlockIndex === -1
                  ? content.blocks.length
                  : activeBlockIndex + 1;

            dispatch({type: ADD_BLOCK, payload: {block, index}});
        };
        const onSelect = (index: number) => dispatch({type: SELECT_BLOCK, payload: index});
        const onContentUpdate = (newContent: PageContent) =>
            dispatch({type: UPDATE_CONTENT, payload: newContent});
        const injectEditBlockProps = ({
            type,
            index: relativeIndex = 0,
            children,
            ...rest
        }: BlockDecorationProps) => {
            const orderedBlocksStartIndex = contentHasHeader ? 1 : 0;
            const isHeader = checkIsHeader(type);
            const index = isHeader ? 0 : relativeIndex + orderedBlocksStartIndex;
            const isActive = activeBlockIndex === index;
            const actions: EditBlockActions = {
                [EditBlockControls.Delete]: () => dispatch({type: DELETE_BLOCK, payload: index}),
            };

            if (!isHeader) {
                actions[EditBlockControls.Copy] = () =>
                    dispatch({type: COPY_BLOCK, payload: index});

                if (index > orderedBlocksStartIndex) {
                    actions[EditBlockControls.Up] = () =>
                        dispatch({
                            type: ORDER_BLOCK,
                            payload: {oldIndex: index, newIndex: index - 1},
                        });
                }

                if (index < content.blocks.length - 1) {
                    actions[EditBlockControls.Down] = () =>
                        dispatch({
                            type: ORDER_BLOCK,
                            payload: {oldIndex: index, newIndex: index + 1},
                        });
                }
            }

            return {
                children,
                isHeader,
                isActive,
                actions,
                onSelect: () => onSelect(index),
                ...rest,
            } as EditBlockProps;
        };

        return {
            activeBlockIndex,
            content,
            errorBoundaryState,
            injectEditBlockProps,
            onAdd,
            onSelect,
            onContentUpdate,
        };
    }, [content, activeBlockIndex, errorBoundaryState, custom]);
}
